export const HOA12_CHUONG6_HANDBOOK = [{"title":"1. Cấu Tạo & Liên Kết Trong Tinh Thể Kim Loại","icon":"🧊","content":["Tinh thể kim loại gồm các ion dương kim loại ở các nút mạng và các electron tự do chuyển động hỗn loạn giữa các ion dương.","<b>Liên kết kim loại:</b> Là liên kết được hình thành do lực hút tĩnh điện giữa các ion dương kim loại và các electron tự do trong mạng tinh thể.","<b>3 kiểu mạng tinh thể phổ biến:</b> Lập phương tâm diện (Cu, Ag, Au, Al), Lập phương tâm khối (Na, K, Fe, Cr, Ba), Lục phương (Be, Mg, Zn)."]},{"title":"2. Tính Chất Vật Lý & Hóa Học Của Kim Loại","icon":"⚔️","content":["<b>4 tính chất vật lý chung</b> do electron tự do gây ra: Tính dẻo (Au > Ag > Al > Cu), Tính dẫn điện (Ag > Cu > Au > Al > Fe), Tính dẫn nhiệt (tương tự dẫn điện), Ánh kim.","<b>Tính chất riêng:</b> Kim loại nhẹ nhất (Li, 0,534 g/cm³), nặng nhất (Os, 22,6 g/cm³); Nóng chảy thấp nhất (Hg, -39°C), cao nhất (W, 3422°C); Mềm nhất (Cs), cứng nhất (Cr).","<b>Tính chất hóa học đặc trưng:</b> Tính khử: M → M<sup>n+</sup> + ne. Tác dụng phi kim, acid loãng/đặc, nước và muối."]},{"title":"3. Phương Pháp Tách & Điều Chế Kim Loại","icon":"⛏️","content":["<b>Nhiệt luyện:</b> Dùng C, CO, H<sub>2</sub>, Al khử oxide kim loại ở nhiệt độ cao (kim loại sau Al trong dãy hoạt động).","<b>Thủy luyện:</b> Dùng dung dịch hòa tan quặng rồi dùng kim loại mạnh hơn đẩy kim loại yếu ra khỏi muối (Cu, Ag, Au).","<b>Điện phân:</b> Điện phân nóng chảy (kim loại mạnh Li → Al); Điện phân dung dịch (kim loại sau Al)."]},{"title":"4. Ăn Mòn Kim Loại & Phương Pháp Bảo Vệ","icon":"🛡️","content":["<b>Ăn mòn điện hóa:</b> Cần 3 điều kiện: (1) 2 điện cực khác nhau về bản chất; (2) cùng tiếp xúc dung dịch điện ly; (3) nối trực tiếp hoặc gián tiếp. Kim loại có tính khử mạnh hơn bị ăn mòn.","<b>Phương pháp bảo vệ:</b> Bảo vệ bề mặt (sơn, mạ, tra dầu mỡ) và Bảo vệ điện hóa (gắn kim loại có tính khử mạnh hơn như Zn làm vật hy sinh bảo vệ vỏ tàu biển bằng thép)."]}];

// ============================================================================
// HỆ THỐNG QUẢN LÝ TIẾN ĐỘ & GAMIFICATION LOCALSTORAGE
// ============================================================================
const STORAGE_PREFIX = 'hoa12_c6_';

export interface Chuong6ExamAttempt {
  id: string;
  examId: string;
  examTitle: string;
  score: number;
  part1Score: number;
  part2Score: number;
  part3Score: number;
  correctCount: number;
  totalQuestions: number;
  durationSeconds: number;
  tabSwitchCount: number;
  autoSubmittedDueToViolation?: boolean;
  date: string;
  formattedDate: string;
  answers: Record<string | number, any>;
}

export interface Chuong6UserProgress {
  completedLessons: string[];
  examAttempts: Record<string, Chuong6ExamAttempt[]>;
  highestScores: Record<string, number>;
  totalTimeSpentSeconds: number;
  bookmarks: string[];
  streakDays: number;
  lastActiveDate: string;
  xpPoints: number;
}

export function getChuong6UserProgress(): Chuong6UserProgress {
  try {
    const saved = localStorage.getItem(`${STORAGE_PREFIX}user_progress`);
    if (saved) return JSON.parse(saved);
  } catch (e) {
    console.error('Error loading Chuong 6 progress:', e);
  }
  return {
    completedLessons: [],
    examAttempts: {},
    highestScores: {},
    totalTimeSpentSeconds: 0,
    bookmarks: [],
    streakDays: 1,
    lastActiveDate: new Date().toISOString(),
    xpPoints: 0
  };
}

export function calculateChuong6ExamScore(questionsInput: any, userAnswers: Record<string | number, any>) {
  const questions: Chuong6Question[] = Array.isArray(questionsInput) 
    ? questionsInput 
    : (questionsInput?.questions || []);

  if (!questions || questions.length === 0) {
    return { totalScore: 0, part1Score: 0, part2Score: 0, part3Score: 0, correctCount: 0, totalQuestions: 0 };
  }

  let part1Score = 0;
  let part2Score = 0;
  let part3Score = 0;
  let correctCount = 0;

  questions.forEach(q => {
    const ans = userAnswers[q.id] || userAnswers[q.number] || userAnswers[q.displayNumber];
    if (ans === undefined || ans === null) return;

    if (q.part === 1) {
      const userLetter = typeof ans === 'string' ? ans.toUpperCase().trim() : '';
      const correctLetter = (q.correctAnswer || '').toUpperCase().trim();
      const matchedOpt = q.options?.find(o => o.isCorrect)?.letter?.toUpperCase()?.trim();
      if ((correctLetter && userLetter === correctLetter) || (matchedOpt && userLetter === matchedOpt)) {
        part1Score += 0.25;
        correctCount += 1;
      }
    } else if (q.part === 2) {
      if (typeof ans === 'object' && ans !== null) {
        let correctSubCount = 0;
        ['a', 'b', 'c', 'd'].forEach(subKey => {
          const userSubVal = ans[subKey];
          if (userSubVal === undefined || userSubVal === null) return;
          const opt = q.options?.find(o => o.letter?.toLowerCase() === subKey);
          if (opt && opt.isCorrect !== undefined) {
            const actualBool = Boolean(opt.isCorrect);
            const userBool = (userSubVal === true || userSubVal === 'true' || userSubVal === 'Đúng' || userSubVal === 'dung');
            if (actualBool === userBool) correctSubCount += 1;
          }
        });
        if (correctSubCount === 1) part2Score += 0.1;
        else if (correctSubCount === 2) part2Score += 0.25;
        else if (correctSubCount === 3) part2Score += 0.5;
        else if (correctSubCount === 4) {
          part2Score += 1.0;
          correctCount += 1;
        }
      }
    } else if (q.part === 3) {
      const userText = String(ans).trim().toLowerCase().replace(',', '.');
      const correctText = String(q.correctAnswer || '').trim().toLowerCase().replace(',', '.');
      if (correctText && userText === correctText) {
        part3Score += 0.5;
        correctCount += 1;
      }
    }
  });

  const totalScore = Math.min(10, Math.round((part1Score + part2Score + part3Score) * 100) / 100);
  return {
    totalScore,
    part1Score: Math.round(part1Score * 100) / 100,
    part2Score: Math.round(part2Score * 100) / 100,
    part3Score: Math.round(part3Score * 100) / 100,
    correctCount,
    totalQuestions: questions.length
  };
}

export function getChuong6ExamHistory(examId?: string): Chuong6ExamAttempt[] {
  try {
    const key = examId ? `${STORAGE_PREFIX}history_${examId}` : `${STORAGE_PREFIX}history_all`;
    const saved = localStorage.getItem(key);
    return saved ? JSON.parse(saved) : [];
  } catch (e) {
    return [];
  }
}

export function saveChuong6ExamAttempt(attempt: Chuong6ExamAttempt) {
  try {
    const examKey = `${STORAGE_PREFIX}history_${attempt.examId}`;
    const examHist: Chuong6ExamAttempt[] = JSON.parse(localStorage.getItem(examKey) || '[]');
    examHist.unshift(attempt);
    localStorage.setItem(examKey, JSON.stringify(examHist.slice(0, 30)));

    const allKey = `${STORAGE_PREFIX}history_all`;
    const allHist: Chuong6ExamAttempt[] = JSON.parse(localStorage.getItem(allKey) || '[]');
    allHist.unshift(attempt);
    localStorage.setItem(allKey, JSON.stringify(allHist.slice(0, 50)));

    const prog = getChuong6UserProgress();
    const curHigh = prog.highestScores[attempt.examId] || 0;
    if (attempt.score > curHigh) {
      prog.highestScores[attempt.examId] = attempt.score;
    }
    prog.xpPoints += Math.round(attempt.score * 10);
    localStorage.setItem(`${STORAGE_PREFIX}user_progress`, JSON.stringify(prog));
  } catch (e) {
    console.error('Error saving exam attempt:', e);
  }
}

export function saveChuong6ExamResult(examId: string, score: number, durationSeconds: number = 0) {
  saveChuong6ExamAttempt({
    id: `att_${Date.now()}`,
    examId,
    examTitle: examId,
    score,
    part1Score: 0,
    part2Score: 0,
    part3Score: 0,
    correctCount: 0,
    totalQuestions: 28,
    durationSeconds,
    tabSwitchCount: 0,
    date: new Date().toISOString(),
    formattedDate: new Date().toLocaleDateString('vi-VN'),
    answers: {}
  });
}

export function shuffleChuong6Exam(exam: Chuong6Exam): Chuong6Exam {
  if (!exam || !exam.questions) return exam;
  const p1 = exam.questions.filter(q => q.part === 1);
  const p2 = exam.questions.filter(q => q.part === 2);
  const p3 = exam.questions.filter(q => q.part === 3);

  const shuffleArr = (arr: any[]) => {
    const res = [...arr];
    for (let i = res.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [res[i], res[j]] = [res[j], res[i]];
    }
    return res;
  };

  const shuffledP1 = shuffleArr(p1);
  const shuffledP2 = shuffleArr(p2);
  const shuffledP3 = shuffleArr(p3);

  let num = 1;
  const renumbered: Chuong6Question[] = [];
  [shuffledP1, shuffledP2, shuffledP3].forEach(subList => {
    subList.forEach(q => {
      renumbered.push({
        ...q,
        number: num,
        displayNumber: num
      });
      num += 1;
    });
  });

  return {
    ...exam,
    questions: renumbered
  };
}

export function getChuong6RankTitle(xp: number): string {
  if (xp >= 500) return '🏅 Bậc Thầy Hóa Học 12';
  if (xp >= 300) return '🌟 Thủ Khoa Triển Vọng';
  if (xp >= 150) return '⚡ Dũng Sĩ Luyện Đề';
  if (xp >= 50)  return '🌱 Chiến Binh Tập Sự';
  return '📚 Tân Binh Khối 12';
}


export const getRankTitle = getChuong6RankTitle;

export class Hoa12Chuong6Service {
  static getLessons() { return HOA12_CHUONG6_LESSONS; }
  static getExams() { return HOA12_CHUONG6_EXAMS; }
  static getHandbook() { return HOA12_CHUONG6_HANDBOOK; }
}
